local config = {
  ui_story_30790101_1_dialog_content = "Alright. Let me measure the size of this part first...",
  ui_story_30790101_2_dialog_content = "It's kind of tall. I'll try standing on tip toes.",
  ui_story_30790101_3_dialog_content = "Huh? What are you doing, Michenny?",
  ui_story_30790101_4_dialog_content = "As you can see, I'm \"<color=#FFB400>measuring</color>.\"",
  ui_story_30790101_5_dialog_content = "Which is a key step to take before \"<color=#FFB400>assessing</color>.\"",
  ui_story_30790101_6_dialog_content = "Precise measurements must be acquired to \"assess\" the true value of a target.",
  ui_story_30790101_7_option_content = "What are you measuring then?",
  ui_story_30790101_8_dialog_content = "As you can see, I'm measuring the size of Soroz.",
  ui_story_30790101_9_dialog_content = "Soroz?!",
  ui_story_30790101_10_dialog_content = "Why are you measuring it?",
  ui_story_30790101_11_dialog_content = "Because I need to assess its value.",
  ui_story_30790101_12_option_content = "What are you assessing?",
  ui_story_30790101_13_dialog_content = "I'm assessing the value of Soroz at the request of Vice.",
  ui_story_30790101_14_dialog_content = "Soroz?!",
  ui_story_30790101_15_dialog_content = "Why are you assessing it?",
  ui_story_30790101_16_dialog_content = "Because then when someone slips on the floor in Soroz and needs to file a claim for damages against Navigator, we'll know what the amount of compensation should be.",
  ui_story_30790101_17_dialog_content = "W-what?!",
  ui_story_30790101_18_dialog_content = "Wait, start from the beginning. Why are you filing a claim for damages against me? Also, who slipped? How did it happen?",
  ui_story_30790101_19_dialog_content = "Here's what happened.",
  ui_story_30790101_20_dialog_content = "It's because the cleaning is done too well in the Colossus.",
  ui_story_30790101_21_dialog_content = "The floor of the hallway is as smooth as a mirror.",
  ui_story_30790101_22_dialog_content = "That's why Vice slipped when she passed through.",
  ui_story_30790101_23_dialog_content = "Vice? Is she okay?",
  ui_story_30790101_24_dialog_content = "I don't think she was physically harmed.",
  ui_story_30790101_25_dialog_content = "But I heard her mumbling about how unlucky she was, and that if she got hurt because of this, she was going to get even with the Navigator.",
  ui_story_30790101_26_dialog_content = "Me?",
  ui_story_30790101_27_dialog_content = "Oh... Here's what happened. I was passing through the hallway this morning when I saw that the floor was a little dirty.",
  ui_story_30790101_28_dialog_content = "So I wiped it a little.",
  ui_story_30790101_29_dialog_content = "Did I clean it too well?",
  ui_story_30790101_30_dialog_content = "How it happened doesn't matter to me. I only care about the \"assessment\" itself.",
  ui_story_30790101_31_dialog_content = "Since there is a member of Soroz here, there's a possibility that <color=#FFB400>someone may ask the Navigator to compensate for the falling</color>...",
  ui_story_30790101_32_dialog_content = "So I must be prepared for \"assessing.\"",
  ui_story_30790101_33_dialog_content = "Which is why I'm \"measuring\" Soroz.",
  ui_story_30790101_34_dialog_content = "So then if Vice really wants you to \"assess\" her compensation, you'll be able to pay her in Nightium based on the size of Soroz.",
  ui_story_30790101_35_dialog_content = "I see. That makes sense...",
  ui_story_30790101_36_dialog_content = "Wait, no, it doesn't make sense at all! How come I need to pay in Nightium based on the size of Soroz?",
  ui_story_30790101_37_dialog_content = "Never mind whether it makes sense or not... Exactly how much will I need to pay?!",
  ui_story_30790101_38_dialog_content = "Worry not, I'll start \"assessing\" after taking \"measurements.\"",
  ui_story_30790101_39_dialog_content = "According to the rate of <color=#FFB400>ten Nightium</color> per <color=#FFB400>centimeter</color>...",
  ui_story_30790101_40_dialog_content = "How much?!",
  ui_story_30790101_41_dialog_content = "Ten Nightium per centimeter.",
  ui_story_30790101_42_dialog_content = "Right... I have a question.",
  ui_story_30790101_43_option_content = "Is Lumopolis and Illumina 1 cm apart?",
  ui_story_30790101_44_dialog_content = "No, it's the one centimeter on the ruler.",
  ui_story_30790101_45_dialog_content = "Given that you are of Caelestite descent, you may lack general knowledge of the outside world.",
  ui_story_30790101_46_dialog_content = "I'll provide you with a ruler so that you'd have a practical understanding of the concept of distance.",
  ui_story_30790101_47_dialog_content = "After that, please pay the compensation at the rate of ten Nightium per centimeter.",
  ui_story_30790101_48_dialog_content = "Why don't you kill me?",
  ui_story_30790101_49_option_content = "Are Nightium the things of children's imaginations?",
  ui_story_30790101_50_dialog_content = "No, it's the currency used in Lumopolis.",
  ui_story_30790101_51_dialog_content = "You can use it to buy food, water, clothes, and daily necessities...",
  ui_story_30790101_52_dialog_content = "The Nightium are very light but very precious. They can be carried around.",
  ui_story_30790101_53_dialog_content = "Right. Looks like I didn't get it wrong...",
  ui_story_30790101_54_dialog_content = "So if ten Nightium per centimeter is the rate, given how huge Soroz is...",
  ui_story_30790101_55_dialog_content = "You know what? Just kill me.",
  ui_story_30790101_56_dialog_content = "In other words, <color=#FFB400>put you to death</color>?",
  ui_story_30790101_57_dialog_content = "Wait, a new assessment needs to be made now.",
  ui_story_30790101_58_dialog_content = "In accordance with the rules of assessment, the current assessment takes precedence over the previous assessment because it is more urgent.",
  ui_story_30790101_59_dialog_content = "...What? What's the assessment about this time?",
  ui_story_30790101_60_dialog_content = "It's about \"putting the Navigator to death.\" After \"measuring\", the value has been assessed to be 0.01 Nightium...",
  ui_story_30790101_61_dialog_content = "That's how little I'm worth?",
  ui_story_30790101_62_dialog_content = "Yes. But first, please pay me 0.01 Nightium.",
  ui_story_30790101_63_dialog_content = "Wait, pay? You want me to pay you?",
  ui_story_30790101_64_dialog_content = "You want me to pay you 0.01 Nightium for you to put me to death?",
  ui_story_30790101_65_dialog_content = "So I'm actually worth a negative value?",
  ui_story_30790101_66_dialog_content = "That's right. According to the measurements and assessment, the value of the Navigator's life is negative 0.01 Nightium.",
  ui_story_30790101_67_dialog_content = "And <color=#FFB400>putting the Navigator to death</color> is basically <color=#FFB400>owning the Navigator's life</color>.",
  ui_story_30790101_68_dialog_content = "To put the Navigator to death signifies buying the Navigator's life from the Navigator.",
  ui_story_30790101_69_dialog_content = "As the value of the Navigator's life is negative 0.01 Nightium,",
  ui_story_30790101_70_dialog_content = "the Navigator should pay the person who puts him to death 0.01 Nightium.",
  ui_story_30790101_71_dialog_content = "I see.",
  ui_story_30790101_72_option_content = "I am this cheap huh?",
  ui_story_30790101_73_dialog_content = "According to the \"measurements\", you are.",
  ui_story_30790101_74_dialog_content = "Although I'm also quite puzzled. After all, the Navigator is a rare Caelestite.",
  ui_story_30790101_75_dialog_content = "Eclipsites are not rare, but even if it's them, I don't suppose they have to pay you to put them to death.",
  ui_story_30790101_76_option_content = "So people can use my life to make money?",
  ui_story_30790101_77_dialog_content = "Theoretically speaking, yes.",
  ui_story_30790101_78_dialog_content = "However, considering that the Navigator's life can only be used once...",
  ui_story_30790101_79_dialog_content = "If someone else wants to use your life to make money, you must consider whether it is worth it or not.",
  ui_story_30790101_80_dialog_content = [[
After all, when your life's only worth roughly -0.01 Nightium, spending it on pointless matters...
Might lead to some future regrets.]],
  ui_story_30790101_81_dialog_content = "If I use my precious life willy-nilly, I'll definitely regret it.",
  ui_story_30790101_82_dialog_content = "No, I mean are you absolutely sure there's no problem with this assessment?",
  ui_story_30790101_83_dialog_content = "I am. The assessment is based on the <color=#FFB400>Eternal Balance</color>.",
  ui_story_30790101_85_dialog_content = "According to the Eternal Balance's \"measurements\", the life of the Navigator is...",
  ui_story_30790101_86_dialog_content = "Hold on!",
  ui_story_30790101_87_dialog_content = "These scales seem to be missing something...",
  ui_story_30790101_88_dialog_content = "Where are the <color=#FFB400>weights</color>?",
  ui_story_30790101_89_dialog_content = "The weights?",
  ui_story_30790101_90_dialog_content = "Hm... Huh?!",
  ui_story_30790101_91_dialog_content = "The w-weights... The weights... They're gone!",
  ui_story_30790101_92_dialog_content = "Find them then! Where have you been just now?",
  ui_story_30790101_93_dialog_content = "I've been to... to...",
  ui_story_30790101_94_dialog_content = "I don't remember...",
  ui_story_30790101_95_dialog_content = "Oh, hey! Here you are, Michenny.",
  ui_story_30790101_96_dialog_content = "I think I just found your stuff in the hallway.",
  ui_story_30790101_97_dialog_content = "This is yours, isn't it?",
  ui_story_30790101_99_dialog_content = "It's the weight!",
  ui_story_30790101_100_dialog_content = "Yeah, I slipped in the hallway just now...",
  ui_story_30790101_101_dialog_content = "And before I could get up, I saw Michenny walking towards me.",
  ui_story_30790101_102_dialog_content = "The floor was really slippery, and Michenny nearly slipped as well. But she was very agile, so it only made her wobble a bit before she walked on.",
  ui_story_30790101_103_dialog_content = "But when I got up, I found this on the floor.",
  ui_story_30790101_104_dialog_content = "Michenny probably dropped it.",
  ui_story_30790101_105_dialog_content = "I see... You slipped and lost your weights accidentally.",
  ui_story_30790101_106_dialog_content = "Is that why you made so many bizarre \"assessments\"?",
  ui_story_30790101_107_dialog_content = "Bi-bizarre?",
  ui_story_30790101_108_dialog_content = "Yep!",
  ui_story_30790101_X108_dialog_content = "Put the weights back now!",
  ui_story_30790101_109_dialog_content = "Or else I'll have to pay Vice at a rate of ten Nightium per centimeter!",
  ui_story_30790101_110_dialog_content = "And then I'll have to pay you 0.01 Nightium to be put to death!",
  ui_story_30790101_111_dialog_content = "Huh? Ten Nightium per centimeter... You're paying me?",
  ui_story_30790101_112_dialog_content = "I don't know why you're paying me... But how about you pay me first, and then she can put the weight back on?",
  ui_story_30790101_113_dialog_content = "Come on, Michenny! Put the weight back on, please!",
  ui_story_30790101_114_dialog_content = "O-okay.",
  ui_story_30790101_116_dialog_content = "Done.",
  ui_story_30790101_117_dialog_content = "I see... So all the \"assessments\" were carried out without the weight.",
  ui_story_30790101_118_dialog_content = "That means I'll need to reassess...",
  ui_story_30790101_119_dialog_content = "Yeah! Am I really worth only negative 0.01 Nightium?",
  ui_story_30790101_120_dialog_content = "The life of the Navigator is now worth...",
  ui_story_30790101_121_dialog_content = "Oh, it can't be measured with the weight anymore.",
  ui_story_30790101_122_dialog_content = "Looks like not only is the Navigator's life not of negative value,",
  ui_story_30790101_123_dialog_content = "it's also one of the most precious things in the world.",
  ui_story_30790101_124_dialog_content = "Now you get it!",
  ui_story_30790101_125_dialog_content = "Huh? It only took you such a short time to admit that the \"assessments\" you made just now were problematic?",
  ui_story_30790101_126_dialog_content = "Michenny really is something. If it was me, I would be trying to cover it up.",
  ui_story_30790101_X126_dialog_content = "You're pretty frank about it as well, Vice.",
  ui_story_30790101_127_dialog_content = "Wrongful \"assessments\" can't be forgiven.",
  ui_story_30790101_128_dialog_content = "So as soon as any issues are found, they must be rectified immediately.",
  ui_story_30790101_129_dialog_content = "This is also the work ethics an \"assessor\" must abide by.",
  ui_story_30790101_130_dialog_content = "Next, I'll assess the damages the Navigator owes Vice.",
  ui_story_30790101_131_dialog_content = "Huh, so PlayerName really is going to pay me.",
  ui_story_30790101_132_dialog_content = "N-no, there's no need!",
  ui_story_30790101_133_dialog_content = "Just place your weight back on. As to this \"assessment\", as the concerned party, I say there's no need to carry on...",
  ui_story_30790101_134_dialog_content = "Huh?",
  ui_story_30790101_135_dialog_content = "That's right. Rather than carrying out these unnecessary \"assessments\"...",
  ui_story_30790101_136_dialog_content = "Shouldn't you focus more on the \"assessment\" that is right here under your nose?",
  ui_story_30790101_137_dialog_content = "Right under my nose?",
  ui_story_30790101_138_dialog_content = "For example, your Eternal Balance was right here under your nose, but you didn't even notice that the weight was gone.",
  ui_story_30790101_139_dialog_content = "...I see.",
  ui_story_30790101_140_dialog_content = "Indeed. It was my negligence.",
  ui_story_30790101_141_dialog_content = "No, it' wasn't negligence. As an assessor, I've... committed an unforgivable mistake.",
  ui_story_30790101_142_dialog_content = "Thank you, PlayerName, for pointing out my blind spot.",
  ui_story_30790101_143_dialog_content = "From now on, I'll be sure to pay attention to it all the time.",
  ui_story_30790101_144_dialog_content = "*Michenny leaves*",
  ui_story_30790101_145_dialog_content = "Ugh, you sent her away just like that, PlayerName?",
  ui_story_30790101_146_dialog_content = "Huh?",
  ui_story_30790101_147_dialog_content = "You were supposed to pay me because I slipped.",
  ui_story_30790101_148_dialog_content = "But you simply guilt-tripped her and got yourself spared from the debt.",
  ui_story_30790101_149_dialog_content = "Don't expose me. Do you really want me to pay you at a rate of ten Nightium per centimeter?",
  ui_story_30790101_150_dialog_content = "I don't see why not.",
  ui_story_30790101_151_dialog_content = "Spare me.",
  ui_story_30790601_1_dialog_content = "PlayerName, I finally found you.",
  ui_story_30790601_2_dialog_content = "... Michenny? I didn't recognize you with that outfit on.",
  ui_story_30790601_3_dialog_content = "I actually just wanted to consult you about my attire. And I'll compensate you for your time.",
  ui_story_30790601_4_dialog_content = "Attire? Compensation? What are you talking about?",
  ui_story_30790601_5_dialog_content = "I planned on going to the Rediesel Desert and thought this outfit would help me blend in with the environment. What do you think?",
  ui_story_30790601_6_dialog_content = "Did I hear you correctly? You're going to the Rediesel Desert? Lumo nobles hardly ever go there.",
  ui_story_30790601_7_dialog_content = "Please, just answer my question—is this outfit all right?",
  ui_story_30790601_8_dialog_content = "Oh, it's more than all right, you look great.",
  ui_story_30790601_9_dialog_content = "Thank you, this is your reward for answering my question—100 Nightium.",
  ui_story_30790601_10_dialog_content = "Huh? You wanna pay me for just answering a question? No thanks.",
  ui_story_30790601_11_dialog_content = "So you prefer a gem? Unfortunately, the value of this matter doesn't quite warrant a gem.",
  ui_story_30790601_12_dialog_content = "Uh, no... just forget it, I'll take the money, but you have to answer a question for me too... for 100 Nightium.",
  ui_story_30790601_13_dialog_content = "Why are you going to the Rediesel Desert?",
  ui_story_30790601_14_dialog_content = "For this Dunecat.",
  ui_story_30790601_15_dialog_content = "Huh?",
  ui_story_30790601_16_dialog_content = "Meow.",
  ui_story_30790601_17_dialog_content = "What?! Where did the cat come from?",
  ui_story_30790601_18_dialog_content = "I brought it up here.",
  ui_story_30790601_19_dialog_content = "Since when did you have a pet cat?",
  ui_story_30790601_20_dialog_content = "It's not a pet.",
  ui_story_30790601_21_dialog_content = "Why do you have it then?",
  ui_story_30790601_22_dialog_content = "It was caught by an animal trafficker in the Rediesel Desert, and its head was injured during the capture.",
  ui_story_30790601_23_dialog_content = "The trafficker took it to Lumopolis and sold it to some foppish noble who abandoned it by the roadside upon discovering the head injury.",
  ui_story_30790601_24_dialog_content = "I happened to pass by and see what was going on, so I arrested both the noble and the trafficker.",
  ui_story_30790601_25_dialog_content = "Those blasted animal traffickers!",
  ui_story_30790601_26_dialog_content = "I have answered four of your questions in total.",
  ui_story_30790601_27_dialog_content = "O-Okay, I'll pay, but I don't have any on me right now. I'll give you 100 Nightium first, and the rest...",
  ui_story_30790601_28_dialog_content = "There's no need, the standards for such things are not fixed, and I don't mind easing the rules when dealing with impoverished persons such as yourself. Just the 100 Nightium will suffice.",
  ui_story_30790601_29_dialog_content = "I-Impoverished? Well... I guess you got me there...",
  ui_story_30790601_30_dialog_content = "Meow...",
  ui_story_30790601_31_dialog_content = "Looking at the accessories on this Dunecat, I assume that it has an owner, one who must be very anxious right now.",
  ui_story_30790601_32_dialog_content = "So, I need to send it back to the desert as soon as possible.",
  ui_story_30790601_33_dialog_content = "I'll go with you. You've never been to the Rediesel Desert... It's quite dangerous there.",
  ui_story_30790601_34_dialog_content = "In that case... I'll need to make some calculations.",
  ui_story_30790601_35_dialog_content = "Again? You've even pulled out the scales...",
  ui_story_30790601_36_dialog_content = "Escort fee, travel expenses, personal safety expenses, medical expenses, and the added value of being the last Caelestite in the world...",
  ui_story_30790601_37_dialog_content = "The cost is a little too high. It should be easy enough to cover if it's just a broken leg, but if you lose your life...",
  ui_story_30790601_38_dialog_content = "Why do you assume something bad is gonna happen to me?!",
  ui_story_30790601_39_dialog_content = "Assessors must consider and measure all situations precisely.",
  ui_story_30790601_40_dialog_content = "Just think of it as a friend accompanying you to do a good deed, without any costs or danger!",
  ui_story_30790601_41_dialog_content = "That way I need to put friendship on one end of the scale. That's even heavier.",
  ui_story_30790601_42_dialog_content = "Don't overthink things. With the time it took for you to calculate all this, we could've already taken this Dunecat home by now.",
  ui_story_30790601_43_dialog_content = "Indeed, I forgot to consider time expenses just now. Thank you for the reminder.",
  ui_story_30790601_44_dialog_content = "Alright, alright! Let's just hurry up and set off already.",
  ui_story_30790601_45_dialog_content = "So, this is the Rediesel Desert.",
  ui_story_30790601_46_dialog_content = "Yep. Do you know where the Dunecat's home is?",
  ui_story_30790601_47_dialog_content = "No, I don't.",
  ui_story_30790601_48_dialog_content = "So how do we find it?",
  ui_story_30790601_49_dialog_content = "The Dunecat should know.",
  ui_story_30790601_50_dialog_content = "That's right, a lot of animals can track scents to find their way home.",
  ui_story_30790601_51_dialog_content = "Uh, kitty? Duney? Cat-Cat?",
  ui_story_30790601_52_dialog_content = "Zzzz... meow...",
  ui_story_30790601_53_dialog_content = "Michenny, what do you call this cat, anyway?",
  ui_story_30790601_54_dialog_content = "Just call it Dunecat.",
  ui_story_30790601_55_dialog_content = "But I just called it and it completely ignored me... Perhaps we should give it a name.",
  ui_story_30790601_56_dialog_content = "Giving it a name would be like counting it as a pet. Our relationship is simply equal to that of escorter plus escortee.",
  ui_story_30790601_57_dialog_content = "Okay. I thought you really liked this cat.",
  ui_story_30790601_58_dialog_content = "The notion of \"liking\" can easily lead to confusion. Judgment does not require such sentiments.",
  ui_story_30790601_59_dialog_content = "I think the sun's making me dizzy... and your theories are just making me feel worse. I think I'm gonna faint any second.",
  ui_story_30790601_60_dialog_content = "Dunecat, can you find your home?",
  ui_story_30790601_61_dialog_content = "Meow... Zzzz...",
  ui_story_30790601_62_dialog_content = "It rolled over and fell back asleep...",
  ui_story_30790601_63_dialog_content = "Dunecats are nocturnal, meaning they sleep during the day and are primarily active at night. It seems we'll need to wait until nightfall before it can lead us to its home.",
  ui_story_30790601_64_dialog_content = "I have a suggestion—we can ask Sinsa for help. He's the leader of the Rediesel Wrench.",
  ui_story_30790601_65_dialog_content = "Perhaps they can help us find the Dunecat's home, or at least provide us with food and shelter...",
  ui_story_30790601_66_dialog_content = "No, as a noble, I'd rather not deal with those barbarians.",
  ui_story_30790601_67_dialog_content = "You don't know them—they're actually very nice people, and we desperately need food and water right now.",
  ui_story_30790601_68_dialog_content = "My mother raised me with independence training ever since I was an infant, and I was selected by the Hall of Justice, among the others, for my mature and calm demeanor.",
  ui_story_30790601_69_dialog_content = "So, even here in the desert, I believe I can survive without their help.",
  ui_story_30790601_70_dialog_content = "Okay, if that's the case, what do you propose we do now?",
  ui_story_30790601_71_dialog_content = "Our first order of business should be locating a water source. We should look for an oasis or dig a well ourselves.",
  ui_story_30790601_72_dialog_content = "All I can see around here is an endless sea of sand dunes. There's not even a single tree, let alone the faintest sign of an oasis.",
  ui_story_30790601_73_dialog_content = "And how are we supposed to dig a well without tools?",
  ui_story_30790601_74_dialog_content = "We'll dig by hand. It's only sand, after all.",
  ui_story_30790601_75_option_content = "Try dig here",
  ui_story_30790601_76_dialog_content = "There's nothing here.",
  ui_story_30790601_77_option_content = "Try dig again",
  ui_story_30790601_78_dialog_content = "The sand collapsed as soon as I started digging.",
  ui_story_30790601_79_option_content = "The plan failed...",
  ui_story_30790601_80_dialog_content = "We can't just dig blindly like this and pray for a miracle. I remember reading something about this in a book. If you see moss in the desert, it means there's a lot of moisture nearby.",
  ui_story_30790601_81_dialog_content = "Only by digging along the moist areas can we have a chance of finding groundwater.",
  ui_story_30790601_82_dialog_content = "All I can see here are a few plants that look like withered grass—their roots should contain some moisture. I'll go ahead and try pulling some up.",
  ui_story_30790601_83_dialog_content = "Here, this is for you.",
  ui_story_30790601_84_dialog_content = "Are you sure you can eat these dry roots?",
  ui_story_30790601_85_dialog_content = "Of course, this is a desert plant. It must contain water.",
  ui_story_30790601_86_option_content = "Take a bite",
  ui_story_30790601_87_dialog_content = "Baah, it's all sandy.",
  ui_story_30790601_88_option_content = "The plan failed...",
  ui_story_30790601_89_dialog_content = "It's getting late. If the Dunecat doesn't wake up or its head injury hasn't healed yet, we may need to spend a night here.",
  ui_story_30790601_90_dialog_content = "So, we should look for Sin—",
  ui_story_30790601_91_dialog_content = "We should build a simple shelter, such as a small log cabin.",
  ui_story_30790601_92_dialog_content = "A small log cabin?! Are you serious?",
  ui_story_30790601_93_dialog_content = "Yes. I'm not one of those sensitive, unreasonable nobles—all I need is a simple log cabin.",
  ui_story_30790601_94_dialog_content = "Right—if Matthieu were here, he'd probably be suggesting that we construct a golden house, while you simply want the two of us to build a log cabin with our bare hands.",
  ui_story_30790601_95_dialog_content = "The only difficulty here is that there aren't any large trees nearby.",
  ui_story_30790601_96_dialog_content = "Are you sure that's the ONLY difficulty?",
  ui_story_30790601_97_option_content = "The plan failed...",
  ui_story_30790601_98_dialog_content = "Fine, you can call someone from the Rediesel Wrench to help. I'll pay them.",
  ui_story_30790601_99_dialog_content = "But they're not allowed to tell anyone that I hired them. This will be purely an employer-employee arrangement between strangers.",
  ui_story_30790601_100_dialog_content = "How am I supposed to explain something like that to them? They wouldn't accept work from such a high-and-mighty noble. Let's just forget it.",
  ui_story_30790601_101_dialog_content = "Meow...",
  ui_story_30790601_102_dialog_content = "The cat finally woke up!",
  ui_story_30790601_103_dialog_content = "Feeling better, Dunecat? Can you find your way home now?",
  ui_story_30790601_104_dialog_content = "Meow, meow...",
  ui_story_30790601_105_dialog_content = "It can move slowly, but it doesn't seem to have fully recovered yet.",
  ui_story_30790601_106_dialog_content = "Then let it go at its own pace.",
  ui_story_30790601_107_dialog_content = "Your eyes haven't left that cat for a second while you sound completely indifferent.",
  ui_story_30790601_108_dialog_content = "Well, I wouldn't want it to get lost again.",
  ui_story_30790601_109_dialog_content = "Argh! Ouch, ouch, ouch!",
  ui_story_30790601_110_dialog_content = "It's a scorpion! The critter's pinching me and won't let go!",
  ui_story_30790601_111_dialog_content = "What? What should I do? I-I'll help you get it off!",
  ui_story_30790601_112_dialog_content = "No, no, no! You're gonna rip my skin off! Argh! Its pincers are clamping down even harder now!",
  ui_story_30790601_113_dialog_content = "Meow!",
  ui_story_30790601_114_dialog_content = "Huh?! The Dunecat swatted that scorpion and it just let go and ran off in an instant!",
  ui_story_30790601_115_dialog_content = "It's licking your wound, must be disinfecting it.",
  ui_story_30790601_116_dialog_content = "*sob* You're the best cat in the world! You saved my life!",
  ui_story_30790601_117_dialog_content = "...",
  ui_story_30790601_118_dialog_content = "Did I just imagine that? It rolled its eyes at me then turned around and walked away...",
  ui_story_30790601_119_dialog_content = "Indeed, it can't stand you either.",
  ui_story_30790601_120_dialog_content = "You two are giving me exactly the same look now...",
  ui_story_30790601_121_dialog_content = "<color=#e8d9bb>*stomach growling*</color>",
  ui_story_30790601_122_dialog_content = "What was that sound?",
  ui_story_30790601_123_dialog_content = "Haha, you're hungry, I heard your stomach growling. But I'm hungry too.",
  ui_story_30790601_124_dialog_content = "What's hunger? I have never been hungry in my life.",
  ui_story_30790601_125_dialog_content = "Your stomach says otherwise.",
  ui_story_30790601_126_dialog_content = "No, I'm an elegant noble. I never get hungry.",
  ui_story_30790601_127_dialog_content = "<color=#e8d9bb>*groooowwwwl*</color>",
  ui_story_30790601_128_dialog_content = "It's even louder...",
  ui_story_30790601_129_dialog_content = "I-I can take it.",
  ui_story_30790601_130_dialog_content = "Meow.",
  ui_story_30790601_131_dialog_content = "Hmm? The cat caught... a field mouse? It placed it right in front of you, like it's trying to give you something to eat.",
  ui_story_30790601_132_dialog_content = "Thank you, Dunecat, but I really can't eat this kind of thing.",
  ui_story_30790601_133_dialog_content = "Meow.",
  ui_story_30790601_134_dialog_content = "Meow.",
  ui_story_30790601_135_dialog_content = "Whoa! Over there! It's another Dunecat!",
  ui_story_30790601_136_dialog_content = "Are they friends? Maybe it'll lead us to their home? They're walking toward each other!",
  ui_story_30790601_137_dialog_content = "They... huh? They just nodded to each other then parted ways?",
  ui_story_30790601_138_dialog_content = "Does that mean they are not family?",
  ui_story_30790601_139_dialog_content = "This is the nature of the Dunecat. They're solitary hunters who don't need a group or companions. They only help and communicate with each other when necessary.",
  ui_story_30790601_140_dialog_content = "Seriously... the more I see, the more it seems you and these Dunecats are exactly alike.",
  ui_story_30790601_141_dialog_content = "Meow, meow, meow!!!",
  ui_story_30790601_142_dialog_content = "What's wrong, Dunecat?",
  ui_story_30790601_143_dialog_content = "Why is it making that sound? All its hair is standing on end. Does it sense danger?",
  ui_story_30790601_144_dialog_content = "Meow!!!",
  ui_story_30790601_145_dialog_content = "Its eyes... The danger is lurking behind us!",
  ui_story_30790601_146_dialog_content = "It's a snake!",
  ui_story_30790601_147_dialog_content = "No, it's a huge python! Ahhhhhh!",
  ui_story_30790601_148_dialog_content = "Don't be afraid, Dunecat! Stop struggling! I can't hold on to it anymore!",
  ui_story_30790601_149_dialog_content = "It's baring its teeth at the python, like it's trying to protect you!",
  ui_story_30790601_150_dialog_content = "Here—take the Dunecat and run! I'll stall the python!",
  ui_story_30790601_151_dialog_content = "How could I possibly run away and leave you behind? Let's get out of here together!",
  ui_story_30790601_152_dialog_content = "Snakes are natural enemies of Dunecats, so it's certain to strike. Please take the cat away from here, quickly! I can only hold it off for so long!",
  ui_story_30790601_153_dialog_content = "Wait a second, we've been standing here talking for so long, and this python hasn't even attacked us yet.",
  ui_story_30790601_154_dialog_content = "It looks kind of familiar.",
  ui_story_30790601_155_dialog_content = "Ah, it's you, PlayerName.",
  ui_story_30790601_156_dialog_content = "Bringing a lovely lady to a place like this for a date in the middle of the night, it's truly your style.",
  ui_story_30790601_157_dialog_content = "What? When have I ever done anything even remotely close to that?",
  ui_story_30790601_158_dialog_content = "Heheh. Just kidding.",
  ui_story_30790601_159_dialog_content = "What are you doing here? By the way, the python is your Speaker, right?",
  ui_story_30790601_160_dialog_content = "I just happened to be passing by when my Sacred Python detected something unusual nearby and came to check it out.",
  ui_story_30790601_161_dialog_content = "I never would have expected that it'd catch you up to no good!",
  ui_story_30790601_162_dialog_content = "It's not like that. We're doing a good deed—helping this cat find its home.",
  ui_story_30790601_163_dialog_content = "Hmm, the adornments on this little cat are very special. They belong to a tribe deep in the desert.",
  ui_story_30790601_164_dialog_content = "Do you know where its home is?",
  ui_story_30790601_165_dialog_content = "Yes. That tribe is terribly mysterious and has very little contact with the outside world. They believe in the God of the Desert, and regard the Dunecat as a messenger of the heavens.",
  ui_story_30790601_166_dialog_content = "They choose the most beautiful Dunecat every year and adorn it with ornaments, regarding it as their totem and the sacred symbol of the tribe.",
  ui_story_30790601_167_dialog_content = "So it's a very important cat. Can you take us to its tribe?",
  ui_story_30790601_168_dialog_content = "I'm afraid not. That tribe is quite hostile toward strangers. How did you come across this Dunecat anyway?",
  ui_story_30790601_169_dialog_content = "Michenny caught the evil trafficker who stole this cat in Lumopolis.",
  ui_story_30790601_170_dialog_content = "So, it was stolen. In that case, you can't go directly to the tribe, as it may lead to an unpleasant and unnecessary misunderstanding.",
  ui_story_30790601_171_dialog_content = "I'll take the Dunecat back. I still have some connections with them, and they would believe what I say.",
  ui_story_30790601_172_dialog_content = "That sounds like a brilliant idea! What do you think, Michenny?",
  ui_story_30790601_173_dialog_content = "This person... Can we really trust her with the cat?",
  ui_story_30790601_174_dialog_content = "Jeriah's a senior member of the Courier Union, and she's also a friend of mine. We can definitely trust her.",
  ui_story_30790601_175_dialog_content = "How astute of you! You could tell at a glance that I'm not reliable at all!",
  ui_story_30790601_176_dialog_content = "Don't get mad, Jeriah. Michenny's just—",
  ui_story_30790601_177_dialog_content = "Alright, calm down. You should know I'm not that sensitive.",
  ui_story_30790601_178_dialog_content = "... Fine. Please make sure you return it safely. I'll pay you.",
  ui_story_30790601_179_dialog_content = "What a charming little girl. Although she's dressed for the desert, she speaks as though she's in Lumopolis.",
  ui_story_30790601_180_dialog_content = "Since you've entrusted me with this job, let's consider it official Courier Union business.",
  ui_story_30790601_181_dialog_content = "But I'll have to put it to one side for now, until I have time to deliver it.",
  ui_story_30790601_182_dialog_content = "No way! This cat is injured! It needs to return to its family immediately!",
  ui_story_30790601_183_dialog_content = "I'll pay you more... as much as you want.",
  ui_story_30790601_184_dialog_content = "Jeriah, I know you don't usually do these kinds of jobs, but this cat business is something of a special situation. Please...",
  ui_story_30790601_185_dialog_content = "If it's a request from a friend, of course I can prioritize it. If it's a job, however...",
  ui_story_30790601_186_dialog_content = "P-Please treat this as a request from a friend. Although I don't know if you'd be willing to see me as a friend...",
  ui_story_30790601_187_dialog_content = "So the arrogant noble lady is willing to let go of her status. It seems you really care about this little cat.",
  ui_story_30790601_188_dialog_content = "Please, Jeriah! Please help us get the cat to its home. I'll—",
  ui_story_30790601_189_option_content = "Wear a skirt!",
  ui_story_30790601_190_dialog_content = "Oh... I can't believe you'd be willing to go that far...",
  ui_story_30790601_191_dialog_content = "Heheh, there's no way I'm passing up an opportunity like this.",
  ui_story_30790601_192_dialog_content = "What did I say just now?! How could I blurt out something like that...",
  ui_story_30790601_193_option_content = "Meow like a cat!",
  ui_story_30790601_194_dialog_content = "Let me hear. Let's see if you're a natural-born kitty linguist.",
  ui_story_30790601_195_dialog_content = "Meow... meow, meow... meow... This is embarrassing...",
  ui_story_30790601_196_dialog_content = "Hehe, it's quite cute.",
  ui_story_30790601_197_dialog_content = "That was terribly embarrassing, PlayerName, but both the cat and I are very grateful to you.",
  ui_story_30790601_198_dialog_content = "It's nothing, all for the cat... *sob*",
  ui_story_30790601_199_dialog_content = "Alright, I'll bring the cat back safely in no time at all.",
  ui_story_30790601_200_dialog_content = "Great! Thanks!",
  ui_story_30790601_201_dialog_content = "Thank you.",
  ui_story_30790601_202_dialog_content = "So, Michenny, it's time to say goodbye to the kitty.",
  ui_story_30790601_203_dialog_content = "Please let me give it one last hug.",
  ui_story_30790601_204_dialog_content = "Meooow!",
  ui_story_30790601_205_dialog_content = "Kitty, I hope you recover soon. I'll miss you.",
  ui_story_30790601_206_dialog_content = "(Michenny holds the Dunecat in her arms for long, refusing to let go. Her eyes twinkle with what seems like tears.)",
  ui_story_30790601_207_dialog_content = "Michenny...",
  ui_story_30790601_208_dialog_content = "I'm fine.",
  ui_story_30790601_209_dialog_content = "Goodbye, Dunecat.",
  ui_story_30790601_210_dialog_content = "Meow."
}
return config
